Use a runtime toggle flag for counting/overlay and switch it with a key press, e.g. `'c'`.

```python
class ObjectCounter:
    def __init__(self):
        self.counting_enabled = False
        self.object_counts = {}

    def toggle_counting(self):
        self.counting_enabled = not self.counting_enabled

    def count_objects(self, frame, detections):
        if not self.counting_enabled:
            return

        for detection in detections:
            class_id = detection['class_id']
            if class_id not in self.object_counts:
                self.object_counts[class_id] = 0
            self.object_counts[class_id] += 1

        for class_id, count in self.object_counts.items():
            text = f"{class_id}: {count}"
            cv2.putText(frame, text, (10, 30 + 30 * class_id),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 255, 0), 2)
```

In the main loop:

```python
key = cv2.waitKey(1) & 0xFF
if key == ord('c'):
    counter.toggle_counting()
```

This lets users enable or disable the object counting overlay while the app is running.
